:root {
  --bg: #f4f5f7;
  --card: #ffffff;
  --border: #e2e5e9;
  --text: #1c2530;
  --muted: #6b7684;
  --accent: #2f6fed;
  --accent-dark: #1f57c9;
  --danger: #d64545;
  --radius: 10px;
  --shadow: 0 1px 3px rgba(20, 30, 45, 0.08);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.app-header {
  background: var(--card);
  border-bottom: 1px solid var(--border);
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  position: sticky;
  top: 0;
  z-index: 5;
}

.app-header h1 { font-size: 1.3rem; margin: 0; }

.search-bar {
  display: flex;
  gap: 0.5rem;
  flex: 1;
  min-width: 240px;
}

.search-bar input {
  flex: 1;
}

.container {
  max-width: 900px;
  margin: 0 auto;
  padding: 1.5rem;
}

input, textarea, button {
  font: inherit;
}

input[type="text"], input[type="search"], textarea {
  width: 100%;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
}

input:focus, textarea:focus {
  outline: 2px solid var(--accent);
  outline-offset: -1px;
  border-color: var(--accent);
}

button {
  cursor: pointer;
  border: 1px solid var(--accent);
  background: var(--accent);
  color: #fff;
  padding: 0.55rem 1rem;
  border-radius: 8px;
  font-weight: 500;
}

button:hover { background: var(--accent-dark); border-color: var(--accent-dark); }

button.ghost {
  background: transparent;
  color: var(--muted);
  border-color: var(--border);
}
button.ghost:hover { background: #eef0f3; color: var(--text); }

button.danger { background: var(--danger); border-color: var(--danger); }
button.danger:hover { background: #b83636; border-color: #b83636; }

/* Add panel */
.add-panel {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1rem;
  margin-bottom: 1.5rem;
}

.add-row { display: flex; gap: 0.5rem; }
.add-row input { flex: 1; }
.add-row button { white-space: nowrap; }

.add-details { margin-top: 0.75rem; }
.add-details summary { cursor: pointer; color: var(--muted); font-size: 0.9rem; }
.add-details > *:not(summary) { margin-top: 0.5rem; }

.error { color: var(--danger); font-size: 0.9rem; margin: 0.5rem 0 0; }

/* Active filter */
.active-filter {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1rem;
  font-size: 0.9rem;
  color: var(--muted);
}

/* Bookmark list */
.bookmark-list { display: flex; flex-direction: column; gap: 0.85rem; }

.bookmark {
  display: flex;
  gap: 0.9rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 0.9rem;
}

.bookmark .preview {
  flex: 0 0 120px;
  width: 120px;
  height: 80px;
  border-radius: 8px;
  object-fit: cover;
  background: #eef0f3;
  border: 1px solid var(--border);
}

.bookmark .preview.placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--muted);
  font-size: 1.6rem;
}

.bookmark .body { flex: 1; min-width: 0; }

.bookmark .title-row {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.bookmark .favicon { width: 16px; height: 16px; flex: 0 0 16px; border-radius: 3px; }

.bookmark .title {
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bookmark .title:hover { color: var(--accent); text-decoration: underline; }

.bookmark .url {
  color: var(--muted);
  font-size: 0.82rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bookmark .desc {
  font-size: 0.9rem;
  margin: 0.35rem 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.bookmark .note {
  font-size: 0.85rem;
  color: var(--muted);
  background: #f7f8fa;
  border-left: 3px solid var(--border);
  padding: 0.3rem 0.5rem;
  border-radius: 4px;
  margin: 0.35rem 0;
  white-space: pre-wrap;
  word-break: break-word;
}

.tags { display: flex; flex-wrap: wrap; gap: 0.35rem; margin-top: 0.4rem; }

.tag {
  display: inline-block;
  background: #e8effc;
  color: var(--accent-dark);
  border: none;
  font-size: 0.78rem;
  padding: 0.15rem 0.55rem;
  border-radius: 999px;
  cursor: pointer;
}
.tag:hover { background: #d5e2fb; }

.bookmark .actions {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  flex: 0 0 auto;
}
.bookmark .actions button {
  padding: 0.35rem 0.6rem;
  font-size: 0.82rem;
}

.status-pill {
  font-size: 0.72rem;
  color: var(--muted);
  margin-top: 0.3rem;
}
.status-pill.failed { color: var(--danger); }

/* Empty states */
.empty-state {
  text-align: center;
  padding: 3rem 1rem;
  color: var(--muted);
}
.empty-state .empty-title { font-size: 1.15rem; font-weight: 600; color: var(--text); margin-bottom: 0.25rem; }

/* Dialogs */
dialog {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  width: min(480px, 92vw);
  box-shadow: 0 10px 40px rgba(20, 30, 45, 0.25);
}
dialog::backdrop { background: rgba(20, 30, 45, 0.4); }
dialog h2 { margin-top: 0; }
dialog label { display: block; margin-bottom: 0.75rem; font-size: 0.85rem; color: var(--muted); }
dialog label input, dialog label textarea { margin-top: 0.25rem; }

.dialog-actions { display: flex; gap: 0.5rem; align-items: center; margin-top: 0.5rem; }
.dialog-actions .spacer { flex: 1; }

@media (max-width: 560px) {
  .bookmark { flex-direction: column; }
  .bookmark .preview { width: 100%; flex-basis: auto; height: 140px; }
  .bookmark .actions { flex-direction: row; }
}

