(npm start > .harness/runtime/server.log 2>&1 &) ; sleep 2.5 ; cat > shot.mjs <<'EOF'
import { chromium } from '@playwright/test';
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1100, height: 560 } });
await p.goto('http://127.0.0.1:4000/');
await p.waitForSelector('body[data-harness-ready="true"]');
console.log('empty-state visible:', await p.locator('#empty-state').isVisible());
console.log('bookmark count:', await p.locator('.bookmark').count());
await p.screenshot({ path: 'prototypes/bookmark-manager-empty-state.png' });
await b.close();
EOF
PLAYWRIGHT_BROWSERS_PATH=/opt/playwright-browsers node shot.mjs 2>&1 | tail -3; rm -f shot.mjs

